#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "trmm.h"

void init_array(
    int m,
    int n,
    double *alpha,
    double A[20][20],
    double B[20][30]) {
    int i, j;

    *alpha = 1.5;
    for (i = 0; i < m; i++) {
        for (j = 0; j < i; j++) {
            A[i][j] = (double)((i + j) % m) / m;
        }
        A[i][i] = 1.0;
        for (j = 0; j < n; j++) {
            B[i][j] = (double)((n + (i - j)) % n) / n;
        }
    }
}

void print_array(int m, int n, double B[20][30]) {
    int i, j;

    fprintf(stderr, "==BEGIN DUMP_ARRAYS==\n");
    fprintf(stderr, "begin dump: %s", "B");
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++) {
            if ((i * m + j) % 20 == 0)
                fprintf(stderr, "\n");
            fprintf(stderr, "%0.6lf ", B[i][j]);
        }
    fprintf(stderr, "\nend   dump: %s\n", "B");
    fprintf(stderr, "==END   DUMP_ARRAYS==\n");
}

int main() {

    int m = 20;
    int n = 30;

    double alpha;
    double A[20][20];
    double B[20][30];

    init_array(m, n, &alpha, A, B);

    kernel_trmm(alpha, A, B);

    print_array(m, n, B);

    return 0;
}
